# 12_fig3_figure.R: Figure 3 (main, shared EPA pool), its full-pool sensitivity, and supplementary Figures S3.1-S3.2. All plotted values are written to tables/fig3_plotted_values_<pool>.csv
source("common.R"); spp <- readRDS("../bci/out/bci_matrices.rds")$spp; pal4 <- c(Incidence = pal[["petrol"]], `Relative abundance` = pal[["orange"]])
taxon_label <- function(code, comm) ifelse(comm == COMM[["BCI"]], spp$Latin[match(code, spp$sp)], paste0(toupper(substr(code, 1, 1)), tolower(substring(code, 2))))
q <- function(v, p) unname(quantile(v, p, na.rm = TRUE))
build3 <- function(pool) {
  obs <- read.csv(sprintf("tables/fig3_observed_%s.csv", pool)); bt <- read.csv(sprintf("tables/fig3_bootstrap_draws_%s.csv", pool)); nl <- read.csv(sprintf("tables/fig3_permutation_draws_%s.csv", pool)); tx <- read.csv(sprintf("tables/fig3_taxon_contributions_%s.csv", pool))
  lv <- unname(COMM); fac <- function(d) { d$community <- factor(d$community, lv); d }
  long <- function(d, cols, nm) d |> select(community, order, any_of("draw"), all_of(cols)) |> pivot_longer(all_of(cols), names_to = "quantity", values_to = "value") |> mutate(panel = nm)
  defs <- list(`A  Zeta profile` = c(zeta_inc = "Incidence", zeta_rel = "Relative abundance"),
               `C  Weighted occupancy` = c(occ_w_sim_inc = "Incidence|Similarity", occ_w_dis_inc = "Incidence|Dissimilarity", occ_w_sim_rel = "Relative abundance|Similarity", occ_w_dis_rel = "Relative abundance|Dissimilarity"),
               `D  Weighted local abundance` = c(abund_w_sim_rel = "Relative abundance|Similarity", abund_w_dis_rel = "Relative abundance|Dissimilarity", abund_w_sim_inc = "Incidence|Similarity", abund_w_dis_inc = "Incidence|Dissimilarity"),
               `E  Effective number of taxa` = c(neff_sim_inc = "Incidence|Similarity", neff_sim_rel = "Relative abundance|Similarity", neff_dis_rel = "Relative abundance|Dissimilarity"))
  rows <- list(); for (nm in names(defs)) { cols <- names(defs[[nm]]); o <- long(obs, cols, nm) |> mutate(draw = 0); b <- long(bt, cols, nm); s <- b |> group_by(community, order, quantity, panel) |> summarise(lo = q(value, .025), hi = q(value, .975), .groups = "drop"); rows[[nm]] <- left_join(o, s, by = c("community", "order", "quantity", "panel")) |> mutate(label = defs[[nm]][quantity]) }
  P <- bind_rows(rows) |> separate(label, c("repr", "kind"), sep = "\\|", fill = "right") |> fac(); P$kind[is.na(P$kind)] <- "Similarity"
  # --- null (within-site abundance permutations) for effective number and components
  nsum <- nl |> filter(permutation > 0) |> group_by(community, order) |> summarise(across(c(neff_sim_rel, neff_dis_rel, D_O, D_H, zeta_rel, occ_w_sim_rel, abund_w_sim_rel), list(med = median, lo = ~ q(., .025), hi = ~ q(., .975))), .groups = "drop") |> fac()
  # --- B: concentration of contributions (top 5 / top 20 taxa share)
  conc <- tx |> group_by(community, order) |> summarise(across(c(sim_rel, dis_rel, sim_inc, dis_inc), list(top5 = ~ sum(sort(., decreasing = TRUE)[1:5]) / sum(.), top20 = ~ sum(sort(., decreasing = TRUE)[1:20]) / sum(.))), .groups = "drop") |> pivot_longer(-c(community, order), names_to = "key", values_to = "value") |> separate(key, c("kind", "repr", "top"), sep = "_") |>
    mutate(kind = ifelse(kind == "sim", "Similarity", "Dissimilarity"), repr = ifelse(repr == "rel", "Relative abundance", "Incidence"), top = ifelse(top == "top5", "Top 5 taxa", "Top 20 taxa")) |> fac()
  # --- F: components
  comp <- obs |> transmute(community, order, `Shared abundance (zeta^A)` = zeta_rel, `Occupancy (D_O)` = D_O, `Abundance heterogeneity (D_H)` = D_H) |> pivot_longer(-c(community, order)) |> fac(); comp$name <- factor(comp$name, c("Shared abundance (zeta^A)", "Occupancy (D_O)", "Abundance heterogeneity (D_H)"))
  th3 <- th() + theme(legend.position = "bottom", legend.box = "horizontal", panel.spacing = unit(4, "mm")); xs <- scale_x_log10(breaks = c(2, 3, 5, 10, 20, 50, 120, 480))
  lab_y <- function(l) labs(x = "Zeta order k (number of sites per set)", y = l, colour = NULL, linetype = NULL, fill = NULL)
  ln <- function(d, ytrans = "identity") ggplot(d, aes(order, value, colour = repr, linetype = kind)) + geom_ribbon(aes(ymin = lo, ymax = hi, fill = repr, group = interaction(repr, kind)), alpha = .15, colour = NA, show.legend = FALSE) + geom_line(linewidth = .5) + geom_point(size = .7) + facet_wrap(~community, nrow = 1, scales = "free_x") + xs + scale_colour_manual(values = pal4) + scale_fill_manual(values = pal4, guide = "none") + scale_y_continuous(trans = ytrans) + th3
  A <- ln(P |> filter(panel == "A  Zeta profile") |> mutate(kind = "Similarity"), "log10") + lab_y("Zeta (taxa; proportion)") + guides(linetype = "none")
  B <- ggplot(conc |> filter(top == "Top 5 taxa"), aes(order, value, colour = repr, linetype = kind)) + geom_line(linewidth = .5) + geom_point(size = .6) + facet_wrap(~community, nrow = 1, scales = "free_x") + xs + scale_colour_manual(values = pal4) + coord_cartesian(ylim = c(0, 1)) + lab_y("Share of similarity or dissimilarity\nfrom the five top-ranked taxa") + th3
  C <- ln(P |> filter(panel == "C  Weighted occupancy")) + lab_y("Contribution-weighted occupancy") + coord_cartesian(ylim = c(0, 1))
  Dd <- ln(P |> filter(panel == "D  Weighted local abundance")) + lab_y("Contribution-weighted local abundance\n(mean proportion where present)")
  E <- ggplot() + geom_ribbon(data = nsum, aes(order, ymin = neff_sim_rel_lo, ymax = neff_sim_rel_hi), fill = pal[["grey"]], alpha = .25) + geom_line(data = nsum, aes(order, neff_sim_rel_med, colour = "Relative abundance, shuffled within sites"), linetype = 2, linewidth = .5) +
    geom_line(data = P |> filter(panel == "E  Effective number of taxa", quantity %in% c("neff_sim_rel", "neff_sim_inc")), aes(order, value, colour = repr, linetype = kind), linewidth = .5) + geom_point(data = P |> filter(panel == "E  Effective number of taxa", quantity %in% c("neff_sim_rel", "neff_sim_inc")), aes(order, value, colour = repr), size = .7) +
    facet_wrap(~community, nrow = 1, scales = "free_x") + xs + scale_y_log10() + scale_colour_manual(values = c(pal4, `Relative abundance, shuffled within sites` = pal[["grey"]])) + lab_y("Effective number of taxa\ncontributing to similarity") + th3 + guides(linetype = "none")
  Fp <- ggplot(comp, aes(order, value, fill = name)) + geom_area(position = "stack", colour = "white", linewidth = .2) + geom_line(data = nsum |> transmute(community, order, value = zeta_rel_med + D_O_med, name = NA), aes(order, value), inherit.aes = FALSE, colour = NA) + facet_wrap(~community, nrow = 1, scales = "free_x") + scale_x_log10(breaks = c(2, 3, 5, 10, 20, 50, 120, 480), expand = expansion(mult = .01)) + scale_y_continuous(expand = c(0, 0)) + scale_fill_manual(values = c(pal[["sage"]], pal[["petrol"]], pal[["orange"]]), labels = c(expression(zeta[k]^A), expression(D[O](k)), expression(D[H](k)))) +
    geom_line(data = nsum, aes(order, D_H_med + 0, linetype = "Shuffled-abundance D_H (median)"), inherit.aes = FALSE, colour = "black", linewidth = .5) + scale_linetype_manual(values = 2, name = NULL) + lab_y("Share of composition (sums to 1)") + th3
  list(plot = (A / B / C / Dd / E / Fp) + plot_annotation(tag_levels = "A") & theme(plot.tag = element_text(face = "bold", size = 9)), values = bind_rows(P |> mutate(table = "profile_weighted_neff"), conc |> mutate(table = "concentration"), comp |> mutate(table = "components"), nsum |> mutate(table = "null_summary")), tx = tx, nsum = nsum, obs = obs) }
for (pool in c("shared", "full")) { r <- build3(pool); sv(r$plot, if (pool == "shared") "Figure3_main" else "FigureS3_full_pool_sensitivity", 7.4, 11.5); write.csv(r$values, sprintf("tables/fig3_plotted_values_%s.csv", pool), row.names = FALSE); if (pool == "shared") R3 <- r }
# ---- S3.1: named taxa contributions (shared pool, relative abundance, similarity and dissimilarity) at orders 2, intermediate and maximum
tx <- R3$tx |> mutate(community = factor(community, unname(COMM)), taxon_name = taxon_label(taxon, as.character(community))); ords <- tx |> group_by(community) |> summarise(o = list(sort(unique(order))[c(1, ceiling(length(unique(order)) / 2), length(unique(order)))]), .groups = "drop")
top <- bind_rows(lapply(seq_len(nrow(ords)), function(i) { d <- tx |> filter(community == ords$community[i], order %in% ords$o[[i]]); bind_rows(lapply(split(d, d$order), function(z) { z$share_sim <- z$sim_rel / sum(z$sim_rel); z$share_dis <- z$dis_rel / sum(z$dis_rel); z[order(-z$share_dis), ][1:8, ] })) })) |> pivot_longer(c(share_sim, share_dis), names_to = "kind", values_to = "share") |> mutate(kind = ifelse(kind == "share_sim", "Similarity", "Dissimilarity"), lab = sprintf("%s (o=%.2f)", taxon_name, occupancy))
write.csv(top |> select(community, order, taxon, taxon_name, occupancy, local_abundance, kind, share), "tables/figS3_1_top_taxa_shared.csv", row.names = FALSE)
pS1 <- ggplot(top, aes(share, reorder(lab, share), fill = kind)) + geom_col(position = "dodge", width = .7) + facet_wrap(vars(community, order), scales = "free", ncol = 3, labeller = labeller(order = function(x) paste("k =", x))) + scale_fill_manual(values = c(Similarity = pal[["petrol"]], Dissimilarity = pal[["orange"]]), name = NULL) + labs(x = "Share of relative-abundance similarity / dissimilarity", y = "Taxon (occupancy, o)") + th(6) + theme(legend.position = "bottom", axis.text.y = element_text(size = 4.5), strip.text.y = element_text(size = 5))
sv(pS1, "FigureS3_1_taxon_contributions", 9, 9)
# ---- S3.2: within-site permutation null for occupancy, local abundance and components
nl <- R3$nsum; ob <- R3$obs |> mutate(community = factor(community, unname(COMM))); mm <- bind_rows(lapply(list(c("D_H", "D_H", "Abundance heterogeneity D_H"), c("D_O", "D_O", "Occupancy D_O"), c("zeta_rel", "zeta_rel", "Shared abundance zeta^A"), c("occ_w_sim_rel", "occ_w_sim_rel", "Weighted occupancy (similarity)"), c("abund_w_sim_rel", "abund_w_sim_rel", "Weighted local abundance (similarity)"), c("neff_dis_rel", "neff_dis_rel", "Effective taxa (dissimilarity)")), function(z) data.frame(community = ob$community, order = ob$order, observed = ob[[z[1]]], null_med = nl[[paste0(z[2], "_med")]], null_lo = nl[[paste0(z[2], "_lo")]], null_hi = nl[[paste0(z[2], "_hi")]], quantity = z[3])))
write.csv(mm, "tables/figS3_2_permutation_null_shared.csv", row.names = FALSE)
pS2 <- ggplot(mm, aes(order)) + geom_ribbon(aes(ymin = null_lo, ymax = null_hi), fill = pal[["grey"]], alpha = .3) + geom_line(aes(y = null_med), linetype = 2, colour = pal[["grey"]]) + geom_line(aes(y = observed), colour = pal[["orange"]]) + geom_point(aes(y = observed), colour = pal[["orange"]], size = .7) + facet_grid(quantity ~ community, scales = "free") + scale_x_log10(breaks = c(2, 3, 5, 10, 20, 50, 120, 480)) + labs(x = "Zeta order k", y = "Observed (orange) and within-site shuffled (grey: median, 2.5-97.5%)") + th(6)
sv(pS2, "FigureS3_2_permutation_null", 7.4, 9); cat("fig3 done\n")
